private val dbSlots = Semaphore(permits = 8)   // one semaphore per dependency

suspend fun query(sql: String): Rows =
    dbSlots.withPermit {                     // suspends, never blocks a thread
        db.query(sql)
    }
// fail fast: if (!dbSlots.tryAcquire()) return Busy

private val dbDispatcher = Dispatchers.IO.limitedParallelism(8)

suspend fun query(sql: String): Rows = withContext(dbDispatcher) {
    db.query(sql)      // blocking call confined to at most 8 threads
}

